# 集合运算:交集 & 并集 | 差集 -
setA = {1, 2, 3, 4}
setB = {3, 4, 5, 6}
print(setA & setB)   # 交集 {3,4}
print(setA | setB)   # 并集 {1..6}
print(setA - setB)   # 差集 {1,2}

